UPDATE pms_sku_stock
SET
stock = CASE id

    WHEN #{item.productSkuId} THEN stock - #{item.productQuantity}

END,
lock_stock = CASE id

    WHEN #{item.productSkuId} THEN lock_stock - #{item.productQuantity}

END
WHERE id IN

    #{item.productSkuId}

UPDATE pms_sku_stock
SET lock_stock = lock_stock + #{quantity}
WHERE id = #{skuId}
  AND stock - lock_stock >= #{quantity}

UPDATE oms_cart_item
SET delete_status = 1, modify_date = NOW()
WHERE member_id = #{memberId}
AND delete_status = 0
AND id IN

    #{id}

UPDATE oms_order SET status = #{status}
WHERE id IN

    #{id}

UPDATE pms_sku_stock
SET lock_stock = CASE id

    WHEN #{item.productSkuId} THEN lock_stock - #{item.productQuantity}

END
WHERE id IN

    #{item.productSkuId}

UPDATE pms_sku_stock
SET lock_stock = lock_stock - #{quantity}
WHERE id = #{skuId}
  AND lock_stock >= #{quantity}

UPDATE oms_order
SET status = #{status}
WHERE id = #{orderId}
  AND status = 0

UPDATE oms_order
SET status = 1,
    payment_time = NOW(),
    pay_type = #{payType}
WHERE id = #{orderId}
  AND status = 0

UPDATE pms_sku_stock
SET stock = stock - #{quantity},
    lock_stock = lock_stock - #{quantity}
WHERE id = #{skuId}
  AND lock_stock >= #{quantity}
  AND stock >= #{quantity}
